<?php
define('ABSPATH','/tmp/');
$GLOBALS['catalog_hooks']=array();
function add_action($hook,$callback,$priority=10,$arguments=1){$GLOBALS['catalog_hooks'][$hook]=true;}
function add_filter($hook,$callback,$priority=10,$arguments=1){$GLOBALS['catalog_hooks'][$hook]=true;}
function register_activation_hook($file,$callback){$GLOBALS['catalog_hooks']['activation']=$callback;}
function wp_parse_url($url,$part){return parse_url($url,$part);}
function home_url($path='/'){return 'https://isohulk.conceptwebactueel-6.nl'.$path;}
class WooCommerce{}
class WP_Error { public $code; public function __construct($code,$message,$data){$this->code=$code;} }
class TestRequest {
  private $m;private $r;
  function __construct($method,$route){$this->m=$method;$this->r=$route;}
  function get_method(){return $this->m;}
  function get_route(){return $this->r;}
}
require dirname(__DIR__).'/isohulk-catalog-only.php';
isohulk_catalog_boot();
foreach(array('woocommerce_is_purchasable','woocommerce_variation_is_purchasable','woocommerce_add_to_cart_validation','woocommerce_checkout_process','rest_pre_dispatch') as $hook) {
 if(empty($GLOBALS['catalog_hooks'][$hook])){fwrite(STDERR,"Missing hook ".$hook."\n");exit(2);}
}
$allowed=isohulk_catalog_block_store_api(null,null,new TestRequest('GET','/wc/store/v1/cart'));
$blocked=isohulk_catalog_block_store_api(null,null,new TestRequest('POST','/wc/store/v1/checkout'));
$add=isohulk_catalog_block_store_api(null,null,new TestRequest('POST','/wc/store/v1/cart/add-item'));
$tax=isohulk_catalog_block_store_api(null,null,new TestRequest('POST','/wc/v3/taxes'));
if($allowed!==null||$tax!==null||!($blocked instanceof WP_Error)||!($add instanceof WP_Error)){exit(3);}
if(isohulk_catalog_price_html('€ 87.00',null)!=='€ 87.00'){exit(4);}
if(strpos(isohulk_catalog_price_html('',null),'Price on request')===false){exit(5);}
if(!isohulk_catalog_is_target()){exit(6);}
if(isohulk_catalog_tax_fields()['woocommerce_prices_include_tax']!=='no'||isohulk_catalog_tax_fields()['woocommerce_tax_display_shop']!=='incl'){exit(7);}
echo "7 catalog mode and VAT contract checks passed\n";
